// One season per stage. The stage -> season assignment lives in course.js
// (`season: "autumn"` ...); everything visual about a season lives here.
//
// Backdrop art:  public/assets/backgrounds/cities/seasons/{city}-{season}.png
//                (generated by tools/make-season-backdrops.py, all 16 combos exist)
// Particle keys: spritesheets loaded in BootScene (germany-city-world pack).

export const SEASONS = Object.freeze({
  spring: {
    de: "FRÜHLING", accent: "#ff9ccf", sky: 0x68baf9,
    street: 0xf2f7ee, streetDeep: 0x8c98b0, prop: 0xfff3f8, ground: "flowers",
    particles: [
      { key: "cologne-petals", count: 22, kind: "fall", vy: [14, 30], vx: [-12, -3], parallax: 0.45, alpha: 0.95 },
      { key: "cologne-bloom", count: 4, kind: "fall", vy: [8, 16], vx: [-8, -2], parallax: 0.6, alpha: 0.9 },
      { key: "cologne-butterflies", count: 3, kind: "float", vx: [10, 22], bob: 9, parallax: 0.7, alpha: 0.95 }
    ]
  },
  summer: {
    de: "SOMMER", accent: "#ffe14d", sky: 0x187ffa,
    street: 0xfff5e0, streetDeep: 0x9a98b4, prop: 0xfffaf0, ground: "none",
    particles: [
      { key: "frankfurt-birds", count: 4, kind: "float", vx: [14, 30], bob: 7, parallax: 0.5, alpha: 0.9 },
      { key: "hamburg-sparkle", count: 8, kind: "twinkle", parallax: 0.55, alpha: 0.9 }
    ]
  },
  autumn: {
    de: "HERBST", accent: "#f2a33a", sky: 0xec9c62,
    street: 0xffe4cc, streetDeep: 0x9c8a9a, prop: 0xffe9d0, ground: "leaves",
    particles: [
      { key: "munich-leaves", count: 12, kind: "fall", vy: [16, 32], vx: [-14, -4], parallax: 0.45, alpha: 0.95 },
      { key: "munich-swirl-leaves", count: 8, kind: "fall", vy: [12, 26], vx: [-18, -6], parallax: 0.6, alpha: 0.9 },
      { key: "munich-sparkle", count: 5, kind: "twinkle", parallax: 0.55, alpha: 0.85 }
    ]
  },
  winter: {
    de: "WINTER", accent: "#a6dcff", sky: 0x92b0d6,
    street: 0xdbe6fb, streetDeep: 0x8fa2c4, prop: 0xdce8ff, ground: "snow",
    particles: [
      { key: null, count: 56, kind: "fall", shape: "rect", size: [1, 2], vy: [16, 36], vx: [-8, -2], parallax: 0.4, alpha: [0.35, 0.7], color: 0xffffff },
      { key: "berlin-sparkle", count: 5, kind: "twinkle", parallax: 0.55, alpha: 0.85 }
    ]
  }
});

export function seasonOf(stage) {
  return SEASONS[stage?.season] || SEASONS.summer;
}

export function backdropKey(stage) {
  return `city-${stage.id}-${stage.season}`;
}

export function backdropUrl(asset, stage) {
  return `${asset}/backgrounds/cities/seasons/${stage.id}-${stage.season}.png`;
}
